/**
 * Putting a frontier job that gave up back in the queue (review 2026-10-10, D-02).
 *
 * The daily, the weekly and the readers' notices are jobs in the product ledger, and the ledger's retry policy gives
 * a job three attempts and then marks it failed for good. Half an hour of database or gateway trouble around 07:30
 * therefore lost that day's issue for ever: nothing asked again once the trouble was over, and the runbook's
 * 「regenerated by the worker's next pass」 was never true. These jobs are idempotent — an issue is inserted
 * `ON CONFLICT DO NOTHING`, a notice is keyed on its recipient and re-checked for eligibility when it runs — so
 * asking again is safe, and seven other modules already do it (`availabilityModule`, `memorySubstrate`, …).
 *
 * What is not safe is asking on every pass: a job that fails every time would get its three attempts every minute,
 * each of them possibly a model call. So the ask is bounded twice (principle 15):
 *
 * - **Once an hour.** The first call asks; the next ask is no sooner than `FRONTIER_JOB_REARM_MS` after the last
 *   one that succeeded. A job that keeps failing gets three attempts an hour. The clock is the process's, so a
 *   restart asks once more — after a restart is when the cause has most often just been fixed.
 * - **Only recent jobs** (`withinMs`). The work of a day that is over, or a notice nobody can still be told, is let
 *   be: an issue is a day's, a safety notice is eligible for a week, and a job that can never succeed is not asked
 *   for ever.
 *
 * What was put back is counted by each caller (`counters.rearmed`) and shows in `/api/ops/metrics`.
 *
 * @module frontierJobRearm
 */

/** The pause between one ask and the next. */
export const FRONTIER_JOB_REARM_MS = 60 * 60_000;

export class FrontierJobRearm {
  /**
   * @param {{ jobs: any, kind: string, limit: number, withinMs: number, everyMs?: number }} options
   *   `jobs` a `ProductJobs` (absent: nothing to ask), `kind` the job kind, `limit` how many jobs one ask puts back,
   *   `withinMs` how recent a job must be.
   */
  constructor({ jobs, kind, limit, withinMs, everyMs = FRONTIER_JOB_REARM_MS }) {
    this.jobs = jobs;
    this.kind = kind;
    this.limit = limit;
    this.withinMs = withinMs;
    this.everyMs = everyMs;
    /** @type {number | null} when the last ask that went through was made */
    this.askedAt = null;
  }

  /**
   * Ask, when it is time to. A failure to ask is thrown and does not use up the hour: the next pass asks again.
   * @param {Date} now
   * @returns {Promise<number>} how many jobs were put back (0 when it is not time yet, or none had given up)
   */
  async run(now) {
    if (!this.jobs) return 0;
    if (this.askedAt !== null && now.getTime() - this.askedAt < this.everyMs) return 0;
    const rearmed = await this.jobs.rearm(this.kind, { limit: this.limit, createdWithinMs: this.withinMs });
    this.askedAt = now.getTime();
    return rearmed;
  }
}
